import crypto from "node:crypto";

// (Extra) a toy dictionary/hash-table attack against unsalted MD5
const md5 = s => crypto.createHash("md5").update(s).digest("hex");
const common = ["123456", "qwerty", "password", "111111"];
const table = Object.fromEntries(common.map(p => [md5(p), p]));   // hash -> password

const leaked = [
  { user: "a", hash: md5("qwerty") },
  { user: "b", hash: md5("qwerty") },     // identical hash => same password
  { user: "c", hash: md5("x9#Lm!2qZr7@Tb") },
];
for (const row of leaked) console.log(row.user, table[row.hash] ?? "not in table");
